```js
const tokenize = q => q.toLowerCase().split(/[\s,]+/).filter(Boolean).slice(0, 8);

function facetMatch(it, o = {}) {
  const domain = o.domain !== undefined ? o.domain : state.domain;
  const subcat = o.subcat !== undefined ? o.subcat : state.subcat;
  const formats = o.formats || state.formats;
  const licenses = o.licenses || state.licenses;
  if (domain && it.domain !== domain) return false;
  if (subcat && it.subcat !== subcat) return false;
  if (formats.size && !formats.has(it.format)) return false;
  if (licenses.size && !licenses.has(it.license)) return false;
  return true;
}

const W = { namePrefix: 60, name: 40, tag: 30, org: 24, sub: 20, dom: 12, desc: 8 };
function scoreItem(it, tokens) {
  if (!tokens.length) return 0;
  const f = F.get(it.id);
  let total = 0;
  for (const t of tokens) {
    let s = 0;
    if (f.name.startsWith(t)) s = W.namePrefix;
    else if (f.name.includes(t)) s = W.name;
    if (!s && f.tags.includes(t)) s = W.tag;
    if (!s && f.org.includes(t)) s = W.org;
    if (!s && f.sub.includes(t)) s = W.sub;
    if (!s && f.dom.includes(t)) s = W.dom;
    if (!s && f.desc.includes(t)) s = W.desc;
    if (!s) return 0;               // every token must hit somewhere
    total += s;
  }
  return total;
}

function currentList(st = state) {
  const tokens = tokenize(st.q);
  const formats = st.formats, licenses = st.licenses; // captured for facetMatch default use — careful: facetMatch reads global state; pass overrides.
  const scored = [];
  for (const it of ITEMS) {
    if (!facetMatchFor(it, st)) continue;
    const s = scoreItem(it, tokens);
    if (tokens.length && !s) continue;
    scored.push([s, it]);
  }
  ...sort by st.sort...
  return scored;
}
