function hl(raw, tokens) {
  if (!tokens.length) return esc(raw);
  const re = new RegExp("(" + tokens.map(reEsc).join("|") + ")", "ig");
  return raw.split(re).map((part, i) => i % 2 ? "<mark>" + esc(part) + "</mark>" : esc(part)).join("");
}
