/* DataAtlas — locate layer for an open-collection registry. */

:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --line: #e3e6ea;
  --line-soft: #eef0f3;
  --text: #141a24;
  --muted: #5c6675;
  --faint: #8a93a3;
  --accent: #3b5bdb;
  --accent-deep: #2b3f9e;
  --accent-weak: #e7ecfd;
  --accent-line: #c3d0f7;
  --mark: #ffe58a;
  --mono: ui-monospace, "Cascadia Mono", Consolas, "SF Mono", Menlo, monospace;
  --radius: 12px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.45 "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.mono { font-family: var(--mono); font-size: 0.92em; }

mark { background: var(--mark); color: inherit; border-radius: 3px; padding: 0 1px; }

/* ---------- top bar ---------- */

.topbar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 10px 20px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
}

.brand { display: flex; align-items: center; gap: 9px; flex: none; }
.brand-mark { width: 21px; height: 21px; fill: var(--accent); }
.brand-name { font-weight: 700; font-size: 1.1rem; letter-spacing: -0.01em; }
.brand-sub { color: var(--faint); font-size: 0.84rem; margin-left: 2px; }

.searchwrap { flex: 1; max-width: 640px; position: relative; display: flex; align-items: center; }
.search-ico { position: absolute; left: 11px; width: 16px; height: 16px; fill: var(--faint); pointer-events: none; }
#search {
  width: 100%;
  border: 1px solid var(--line);
