  margin: 0 0 6px;
  font-size: 0.75rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.07em;
  color: var(--faint);
}

.tree-row {
  display: flex; align-items: center; gap: 7px;
  width: 100%;
  border: 0; background: none; font: inherit; color: var(--text);
  text-align: left;
  padding: 7px 10px; border-radius: 8px;
  cursor: pointer;
}
.tree-row:hover { background: var(--bg); }
.tree-row.sel { background: var(--accent-weak); color: var(--accent-deep); font-weight: 600; }
.tree-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chev { flex: none; color: var(--faint); font-size: 0.7rem; transition: transform 0.15s; }
.tree-node.open .chev { transform: rotate(90deg); }
