.context-right { display: flex; align-items: center; gap: 9px; }
.count { color: var(--muted); font-size: 0.88rem; font-variant-numeric: tabular-nums; }
.sortlab { color: var(--faint); font-size: 0.84rem; }
#sort {
  border: 1px solid var(--line); border-radius: 8px;
  background: var(--panel); color: var(--text);
  font: inherit; font-size: 0.9rem;
