.ver { flex: none; margin-left: auto; color: var(--faint); font-size: 0.8rem; }

.row-meta {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px;
  margin-top: 4px;
  color: var(--muted); font-size: 0.83rem;
  font-variant-numeric: tabular-nums;
}
.row-path { color: var(--accent); font-weight: 500; }
.dot { color: var(--line); }

.row-desc {
  margin: 5px 0 0;
  color: var(--muted); font-size: 0.89rem;
  display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical;
  overflow: hidden;
