@keyframes flash-ring {
  0%   { box-shadow: 0 0 0 3px rgba(59, 91, 219, 0.85); border-color: var(--accent); }
  100% { box-shadow: 0 0 0 3px rgba(59, 91, 219, 0); }
}
.row.flash { animation: flash-ring 1.1s ease-out 2; border-color: var(--accent); }

