.empty { text-align: center; margin-top: 90px; }
.empty-title { font-size: 1.15rem; font-weight: 600; margin: 0 0 4px; }
.empty-hint { color: var(--muted); margin: 0 0 16px; }

/* ---------- buttons ---------- */

.btn {
  border: 1px solid var(--line); border-radius: 9px;
  background: var(--panel); color: var(--text);
  font: inherit; font-size: 0.92rem;
  padding: 8px 14px; cursor: pointer;
