  margin-left: auto; flex: none;
  border: 0; background: var(--bg);
  width: 30px; height: 30px; border-radius: 8px;
  color: var(--muted); font-size: 0.9rem; cursor: pointer;
}
.icon-btn:hover { color: var(--text); background: var(--line-soft); }
.drawer-title { margin: 9px 0 7px; font-size: 1.22rem; line-height: 1.3; }
.drawer-path { display: flex; flex-wrap: wrap; align-items: center; gap: 3px; font-size: 0.88rem; }

.drawer-body { padding: 15px 20px 26px; overflow-y: auto; }
.drawer-org { margin: 0 0 8px; color: var(--muted); }
.drawer-desc { margin: 0 0 12px; }
.drawer-tags { margin: 0 0 4px; }

.meta {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 9px 12px;
  margin: 16px 0 18px; padding: 0;
}
.meta-row {
  background: var(--bg); border: 1px solid var(--line-soft);
  border-radius: 10px; padding: 8px 12px;
}
.meta-row dt {
  font-size: 0.7rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--faint);
}
.meta-row dd { margin: 2px 0 0; font-weight: 600; font-size: 0.93rem; font-variant-numeric: tabular-nums; }

.drawer-actions { display: flex; flex-wrap: wrap; gap: 8px; }

